<?php declare(strict_types=1);require_once dirname(__DIR__,2).'/security.php';$h=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES);$pages=max(1,(int)ceil($total/$perPage));?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Course Reports</title><link rel="stylesheet" href="/assets/style.css"><style>main{max-width:1200px;margin:auto;padding:1rem}.filters,.actions,.pages{display:flex;gap:.6rem;flex-wrap:wrap;align-items:end}.field label{display:block;font-weight:700}.scroll{overflow-x:auto;margin-top:1rem}table{width:100%;border-collapse:collapse}th,td{padding:.65rem;border:1px solid #ccc;text-align:left}@media(max-width:700px){th:nth-child(4),td:nth-child(4){display:none}}</style></head><body><?php require dirname(__DIR__,2).'/nav.php';?><main><h1>Course Reports</h1><p role="status"><?=(int)$total?> accessible report(s)</p><form class="filters" role="search" method="get"><div class="field"><label for="search">Search</label><input id="search" name="search" value="<?=$h($f['search'])?>"></div><?php foreach(['academic_year'=>'Academic year','semester'=>'Semester','status'=>'Status']as$x=>$label):?><div class="field"><label for="<?=$x?>"><?=$label?></label><input id="<?=$x?>" name="<?=$x?>" value="<?=$h($f[$x])?>"></div><?php endforeach;?><button>Filter</button></form><?php if(\QualitySystem\Security\PermissionMatrix::allows($r,'course_reports','create')):?><p><a class="btn" href="/course-reports/create">Create course report</a></p><?php endif;?><div class="scroll" tabindex="0" aria-label="Course report results"><table><caption>Course reports you are authorized to access</caption><thead><tr><th>Course</th><th>Period</th><th>Status</th><th>Coordinator</th><th>Students</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as$row):?><tr><td><strong><?=$h($row['course_code'])?></strong> — <?=$h($row['course_title'])?></td><td><?=$h($row['academic_year'])?> / <?=$h($row['semester'])?></td><td><?=$h($row['status'])?></td><td><?=$h($row['course_coordinator'])?></td><td><?=(int)$row['students_passed']?> passed / <?=(int)$row['students_enrolled']?></td><td><div class="actions"><a href="/view_course_report.php?id=<?=(int)$row['id']?>">View</a><?php if(\QualitySystem\Security\PermissionMatrix::allows($r,'course_reports','update')):?><a href="/course-reports/<?=(int)$row['id']?>/edit">Edit</a><?php endif;?><?php if(\QualitySystem\Security\PermissionMatrix::allows($r,'course_reports','delete')):?><form method="post" action="/course-reports/<?=(int)$row['id']?>/delete" onsubmit="return confirm('Delete this course report?')"><?=csrfField()?><button>Delete</button></form><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6">No accessible reports found.</td></tr><?php endif;?></tbody></table></div><nav class="pages" aria-label="Course report pages"><?php for($n=1;$n<=$pages&&$n<=100;$n++):?><a <?=$n===$page?'aria-current="page"':''?> href="?<?=http_build_query($f+['page'=>$n,'per_page'=>$perPage])?>"><?=$n?></a><?php endfor;?></nav></main></body></html>
